"""Advanced retrieval on handbook.md: chunking strategies, BM25, reciprocal rank fusion, re-ranking and
metadata filters, each measured with the same labelled questions.

Needs handbook.md, queries.json and rag_pipeline.py from the module 1 lab, plus grades.json.
Run: python retrieval_lab.py
"""

import json
import math
import re
from collections import Counter

from sklearn.feature_extraction.text import ENGLISH_STOP_WORDS

from rag_pipeline import Retriever, load_chunks, slug


def tokens(text):
    return [w for w in re.findall(r"[a-z0-9]+", text.lower()) if w not in ENGLISH_STOP_WORDS]


class BM25:
    def __init__(self, docs, k1=1.2, b=0.75):
        self.docs = [tokens(d) for d in docs]
        self.k1, self.b = k1, b
        self.avgdl = sum(len(d) for d in self.docs) / len(self.docs)
        df = Counter(w for d in self.docs for w in set(d))
        n = len(self.docs)
        self.idf = {w: math.log(1 + (n - f + 0.5) / (f + 0.5)) for w, f in df.items()}

    def scores(self, query):
        out = []
        for d in self.docs:
            tf = Counter(d)
            s = 0.0
            for w in tokens(query):
                if w in tf:
                    # TODO 1: add idf * tf * (k1 + 1) / (tf + k1 * (1 - b + b * len(d) / avgdl)): term frequency
                    #         saturates with k1, and b normalises for document length
                    pass
            out.append(s)
        return out


def ranking(scores):
    return sorted(range(len(scores)), key=lambda i: (-scores[i], i))


def rrf(rankings, k=60):
    """Reciprocal rank fusion: each list adds 1 / (k + rank) for every item in it."""
    fused = Counter()
    for order in rankings:
        # TODO 2: for each position (rank from 1) in order, add 1 / (k + rank) to that item's fused score
        pass
    return sorted(fused, key=lambda i: (-fused[i], i))


def mrr(rankings_by_query, relevant_by_query):
    total = 0.0
    for qid, ids in rankings_by_query.items():
        total += 1 / (ids.index(relevant_by_query[qid]) + 1) if relevant_by_query[qid] in ids else 0
    return total / len(rankings_by_query)


def recall_at(rankings_by_query, relevant_by_query, k):
    return sum(relevant_by_query[q] in ids[:k] for q, ids in rankings_by_query.items()) / len(rankings_by_query)


def windows(chunks, size=40, overlap=10):
    """Fixed-size word windows over the whole handbook, ignoring headings. Each window is labelled with the
    section most of its words come from, so it can be scored against the same answers."""
    words, owner = [], []
    for c in chunks:
        w = c["text"].split()
        words += w
        owner += [c["id"]] * len(w)
    out = []
    for start in range(0, len(words), size - overlap):
        part = owner[start:start + size]
        out.append({"id": Counter(part).most_common(1)[0][0], "text": " ".join(words[start:start + size])})
        if start + size >= len(words):
            break
    return out


def best_by_section(order, items):
    """Collapse a ranking of windows to a ranking of distinct section ids."""
    seen = []
    for i in order:
        if items[i]["id"] not in seen:
            seen.append(items[i]["id"])
    return seen


def main():
    chunks = load_chunks()
    with open("queries.json", encoding="utf-8") as f:
        queries = json.load(f)["queries"]
    with open("grades.json", encoding="utf-8") as f:
        grades = json.load(f)["grades"]
    relevant = {q["id"]: q["relevant"] for q in queries}

    # 1. Chunking: section chunks with a contextual header, against plain 40-word windows (both scored with BM25)
    sectioned = BM25([f"{c['topic']}. {c['title']}. {c['text']}" for c in chunks])
    wins = windows(chunks)
    windowed = BM25([w["text"] for w in wins])
    by_section = {q["id"]: [chunks[i]["id"] for i in ranking(sectioned.scores(q["question"]))] for q in queries}
    by_window = {q["id"]: best_by_section(ranking(windowed.scores(q["question"])), wins) for q in queries}
    print(f"Chunking: {len(chunks)} sections with headers recall@3 {recall_at(by_section, relevant, 3):.2f} "
          f"MRR {mrr(by_section, relevant):.2f} | {len(wins)} 40-word windows recall@3 "
          f"{recall_at(by_window, relevant, 3):.2f} MRR {mrr(by_window, relevant):.2f}")

    # 2. Keyword, dense and hybrid retrieval over the section chunks
    dense = Retriever(chunks)
    by_dense = {q["id"]: [c["id"] for _, c in dense.search(q["question"], len(chunks), "dense")] for q in queries}
    by_tfidf = {q["id"]: [c["id"] for _, c in dense.search(q["question"], len(chunks), "tfidf")] for q in queries}
    by_hybrid = {qid: rrf([by_section[qid], by_dense[qid]]) for qid in by_section}
    for name, runs in (("TF-IDF", by_tfidf), ("BM25", by_section), ("LSA", by_dense), ("RRF(BM25, LSA)", by_hybrid)):
        print(f"{name:<15} recall@1 {recall_at(runs, relevant, 1):.2f}  recall@3 {recall_at(runs, relevant, 3):.2f}  "
              f"MRR {mrr(runs, relevant):.2f}")

    # 3. Re-ranking the top 5 hybrid results with relevance grades from a second-stage model
    reranked = {}
    for qid, ids in by_hybrid.items():
        top = ids[:5]
        # TODO 3: sort the top 5 by their grade, grades[qid].get(id, 0), highest first, keeping the
        #         first-stage order for ties, then append the rest of ids unchanged
        reranked[qid] = ids
    print(f"Re-ranking the top 5: recall@1 {recall_at(by_hybrid, relevant, 1):.2f} -> {recall_at(reranked, relevant, 1):.2f}, "
          f"MRR {mrr(by_hybrid, relevant):.2f} -> {mrr(reranked, relevant):.2f}")

    # 4. Metadata filters: finance pages updated in 2026, applied after or before ranking
    question = "I'm moving house soon. What do I need to sort out?"
    allowed = {c["id"] for c in chunks if c["department"] == "finance" and c["updated"] >= "2026-01-01"}
    order = [chunks[i]["id"] for i in ranking(sectioned.scores(question))]
    post = [c for c in order[:3] if c in allowed]
    pre = [c for c in order if c in allowed][:3]
    print(f"Filter finance, updated 2026 or later: post-filtering the top 3 leaves {len(post)} {post}; "
          f"pre-filtering returns {len(pre)} {pre}")


if __name__ == "__main__":
    main()

"""A travel-support agent loop that survives real failures: invalid arguments, a flaky service, an action that
needs the customer's approval, a model that repeats itself, and a budget.

Offline it replays two scripted conversations. With ANTHROPIC_API_KEY and CLAUDE_MODEL set,
python agent_loop.py --live sends the same loop to the real model (add --approve to allow the booking change).
"""

import json
import sys
import time
from types import SimpleNamespace as NS
from typing import Literal

from pydantic import BaseModel, Field, ValidationError

Airport = Literal["LIS", "OPO", "MAD", "BCN"]
Day = Literal["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]


class GetBooking(BaseModel):
    """Look up a booking by its six-letter reference. Use it before searching or changing anything."""
    booking_ref: str = Field(pattern=r"^[A-Z]{6}$", description="Six capital letters, e.g. QXPLMR")


class SearchFlights(BaseModel):
    """Search flights between two airports on a day of the week."""
    origin: Airport
    destination: Airport
    day: Day


class ChangeBooking(BaseModel):
    """Move a booking to another flight. Only call this after the customer has confirmed the new flight."""
    booking_ref: str = Field(pattern=r"^[A-Z]{6}$")
    flight_id: str = Field(pattern=r"^AH\d{3}$")


BOOKINGS = {"QXPLMR": {"passenger": "R. Silva", "flight": "AH101", "origin": "LIS", "destination": "OPO", "day": "Thu"}}
FLIGHTS = [{"id": "AH101", "origin": "LIS", "destination": "OPO", "day": "Thu", "departs": "08:10"},
           {"id": "AH204", "origin": "LIS", "destination": "OPO", "day": "Fri", "departs": "09:40"},
           {"id": "AH206", "origin": "LIS", "destination": "OPO", "day": "Fri", "departs": "18:05"}]


class FlakyFlightService:
    """Stands in for a remote API that times out on its first call."""

    def __init__(self):
        self.calls = 0

    def search(self, args):
        self.calls += 1
        if self.calls == 1:
            raise TimeoutError("flight service timed out")
        return [f for f in FLIGHTS if (f["origin"], f["destination"], f["day"]) == (args.origin, args.destination, args.day)]


SERVICE = FlakyFlightService()
TOOLS = {  # name: (input model, function, read_only)
    "get_booking": (GetBooking, lambda a: BOOKINGS.get(a.booking_ref) or {"error": "no such booking"}, True),
    "search_flights": (SearchFlights, SERVICE.search, True),
    "change_booking": (ChangeBooking, lambda a: {"booking_ref": a.booking_ref, "new_flight": a.flight_id,
                                                 "status": "changed"}, False),
}
TOOL_DEFINITIONS = [{"name": n, "description": m.__doc__, "input_schema": m.model_json_schema()}
                    for n, (m, _, _) in TOOLS.items()]
STATS = {"retries": 0, "refused": 0}


def with_retries(function, args, attempts=3, base_delay=0.0):
    """Retry temporary failures with exponential backoff (base_delay is 0 offline so the script runs instantly)."""
    for attempt in range(1, attempts + 1):
        try:
            return function(args)
        except TimeoutError as e:
            if attempt == attempts:
                raise
            STATS["retries"] += 1
            print(f"         retry {attempt} after {type(e).__name__}")
            time.sleep(base_delay * 2 ** (attempt - 1))


def run_tool(name, tool_input, approve):
    """Returns (result text, is_error). Validates first; retries only read-only tools; gates the rest."""
    if name not in TOOLS:
        return f"Unknown tool {name}. Available: {', '.join(TOOLS)}", True
    model, function, read_only = TOOLS[name]
    try:
        args = model.model_validate(tool_input)
    except ValidationError as e:
        return "Invalid input: " + "; ".join(f"{'.'.join(map(str, x['loc']))}: {x['msg']}" for x in e.errors()), True
    # TODO 1: a tool that isn't read-only needs approve(name, tool_input) first: if it returns False, count it in
    #         STATS["refused"] and return an error telling the model to ask the customer to confirm first
    pass
    try:
        # TODO 2: run read-only tools through with_retries(function, args) and others once (a retried write
        #         could happen twice); return json.dumps(result) and False
        result = function(args)
    except Exception as e:  # report the failure to the model instead of crashing the loop
        return f"{type(e).__name__}: {e}", True
    return json.dumps(result), False


def run_agent(question, create, approve, max_turns=8, max_tool_calls=10, max_repeats=3):
    messages = [{"role": "user", "content": question}]
    calls, errors, seen = 0, 0, {}
    for turn in range(1, max_turns + 1):
        reply = create(tools=TOOL_DEFINITIONS, messages=messages)
        messages.append({"role": "assistant", "content": reply.content})
        if reply.stop_reason == "end_turn":
            text = "".join(b.text for b in reply.content if b.type == "text")
            return f"answered after {turn} turns, {calls} tool calls, {errors} errors: {text}"
        if reply.stop_reason in ("max_tokens", "refusal"):
            return f"stopped: stop_reason {reply.stop_reason} is not a finished answer"
        results = []
        for block in (b for b in reply.content if b.type == "tool_use"):
            key = (block.name, json.dumps(block.input, sort_keys=True))
            seen[key] = seen.get(key, 0) + 1
            # TODO 3: stop the run if this exact call has now been made max_repeats times, or if calls has
            #         reached max_tool_calls, returning a message that says why
            pass
            output, is_error = run_tool(block.name, block.input, approve)
            calls, errors = calls + 1, errors + is_error
            print(f"turn {turn}: {block.name} {json.dumps(block.input)} -> {'ERROR ' if is_error else ''}{output[:80]}")
            results.append({"type": "tool_result", "tool_use_id": block.id, "content": output, "is_error": is_error})
        messages.append({"role": "user", "content": results})
    return f"stopped: no answer within {max_turns} turns"


def call(i, name, args):
    return NS(type="tool_use", id=f"call_{i}", name=name, input=args)


SCENARIOS = {
    "A": ("My booking QXPLMR is on Thursday. Can I move to a Friday morning flight?", [
        [call(1, "get_booking", {"booking_ref": "qxplmr"})],
        [call(2, "get_booking", {"booking_ref": "QXPLMR"})],
        [call(3, "search_flights", {"origin": "LIS", "destination": "OPO", "day": "Fri"})],
        [call(4, "change_booking", {"booking_ref": "QXPLMR", "flight_id": "AH204"})],
        [NS(type="text", text="AH204 leaves Lisbon for Porto on Friday at 09:40. Shall I move your booking to it?")],
    ]),
    "B": ("Are there any flights from Madrid to Barcelona on Sunday?", [
        [call(i, "search_flights", {"origin": "MAD", "destination": "BCN", "day": "Sun"})] for i in range(1, 6)
    ]),
}


def scripted(turns):
    replies = iter(NS(content=c, stop_reason="tool_use" if c[0].type == "tool_use" else "end_turn") for c in turns)
    return lambda **kwargs: next(replies)


def live_create():
    """The only function that talks to the API."""
    import os

    import anthropic

    client = anthropic.Anthropic()
    system = "You help customers of Atlantic Hop, a small airline, change their bookings. Be brief."
    return lambda **kw: client.messages.create(model=os.environ["CLAUDE_MODEL"], max_tokens=1024, system=system, **kw)


def main():
    approve = (lambda name, args: True) if "--approve" in sys.argv else (lambda name, args: False)
    for name, (question, turns) in SCENARIOS.items():
        print(f"Scenario {name}: {question}")
        create = live_create() if "--live" in sys.argv else scripted(turns)
        print("Result:", run_agent(question, create, approve))
    print(f"Retries: {STATS['retries']}, actions refused without approval: {STATS['refused']}")


if __name__ == "__main__":
    main()

