"""Three agents with one job each: a researcher gathers sourced notes, a writer drafts an answer from them, and a
reviewer checks every sentence against the notes, sending drafts back until they pass.

Offline the writer replays drafts.json; with ANTHROPIC_API_KEY and CLAUDE_MODEL set, --live lets the model write.
Needs handbook.md, rag_pipeline.py (module 1 lab) and retrieval_lab.py (module 2 lab). Run: python multi_agent.py
"""

import json
import re
import sys
from dataclasses import dataclass, field

from rag_pipeline import load_chunks
from retrieval_lab import BM25, ranking, tokens


@dataclass
class Task:
    question: str
    max_sources: int = 3


@dataclass
class Note:
    source: str
    text: str


@dataclass
class Draft:
    text: str
    revision: int


@dataclass
class Review:
    approved: bool
    problems: list = field(default_factory=list)


TRACE = []


def send(sender, receiver, message):
    """Every hand-off goes through here, so the whole conversation between agents is logged."""
    kind = f"list of {type(message[0]).__name__}" if isinstance(message, list) else type(message).__name__
    TRACE.append(f"{sender} -> {receiver}: {kind}")
    return message


class Researcher:
    def __init__(self):
        self.chunks = load_chunks()
        self.index = BM25([f"{c['topic']}. {c['title']}. {c['text']}" for c in self.chunks])

    def run(self, task):
        top = ranking(self.index.scores(task.question))[:task.max_sources]
        return [Note(self.chunks[i]["id"], self.chunks[i]["text"]) for i in top]


class Writer:
    def __init__(self, live):
        self.live = live
        with open("drafts.json", encoding="utf-8") as f:
            self.recorded = json.load(f)["drafts"]

    def run(self, task, notes, review, revision):
        if not self.live:
            return Draft(self.recorded[min(revision, len(self.recorded) - 1)], revision)
        return Draft(write_with_model(task, notes, review), revision)


def write_with_model(task, notes, review):
    """The only function that talks to the API."""
    import os

    import anthropic

    sources = "\n".join(f'<note source="{n.source}">{n.text}</note>' for n in notes)
    feedback = ("\nFix these problems from the reviewer: " + "; ".join(review.problems)) if review else ""
    prompt = (f"{sources}\n<question>{task.question}</question>\nAnswer in two or three sentences, using only the "
              f"notes, and end every sentence with its source in square brackets, like [moving-home].{feedback}")
    client = anthropic.Anthropic()
    reply = client.messages.create(model=os.environ["CLAUDE_MODEL"], max_tokens=1024,
                                   messages=[{"role": "user", "content": prompt}])
    return "".join(b.text for b in reply.content if b.type == "text")


class Reviewer:
    def run(self, draft, notes):
        texts = {n.source: n.text for n in notes}
        problems = []
        for sentence in re.split(r"(?<=[.!?\]])\s+(?=[A-Z])", draft.text.strip()):
            cited = re.findall(r"\[([a-z0-9-]+)\]", sentence)
            claim = re.sub(r"\s*\[[a-z0-9-]+\]", "", sentence)
            if not cited or any(c not in texts for c in cited):
                problems.append(f"no valid source: {claim.strip()[:50]}")
                continue
            evidence = " ".join(texts[c] for c in cited)
            # TODO 1: flag the sentence if any number in it is missing from evidence, or if fewer than half of its
            #         content words (tokens(claim)) appear in tokens(evidence)
            pass
        return Review(not problems, problems)


def orchestrate(question, live=False, max_revisions=2):
    task = send("orchestrator", "researcher", Task(question))
    notes = send("researcher", "orchestrator", Researcher().run(task))
    print("Notes from:", ", ".join(n.source for n in notes))
    writer, reviewer, review = Writer(live), Reviewer(), None
    for revision in range(max_revisions + 1):
        draft = send("writer", "reviewer", writer.run(task, notes, review, revision))
        review = send("reviewer", "orchestrator", reviewer.run(draft, notes))
        print(f"Draft {revision + 1}: " + ("approved" if review.approved else "; ".join(review.problems)))
        if review.approved:
            return draft
    return None


def main():
    final = orchestrate("I'm moving out of Lanternfield next month. What do I need to do about council tax and my bins?",
                        live="--live" in sys.argv)
    print("Final answer:", final.text if final else "none approved: escalate to a person")
    print("Trace:", " | ".join(TRACE))


if __name__ == "__main__":
    main()

